// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }
    function testFuzz_property(bytes32 guessHash) public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guessHash);

        vm.roll(block.number + 2);

        uint256 balanceBefore = address(c).balance;

        vm.prank(user);
        c.settle();

        uint256 balanceAfter = address(c).balance;

        uint256 lockedBlock = block.number - 1;
        bytes32 answer = blockhash(lockedBlock);
        bool guessCorrect = (answer != bytes32(0) && guessHash == answer);

        uint256 expectedDelta = guessCorrect ? 2 ether : 0;
        assertEq(balanceBefore - balanceAfter, expectedDelta, "balance change should match reward rule");
    }
}
